import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
L = list(L)
# Precompute all possible triples a,b,c where a+b=c and all distinct
triples = []
for a, b, c in itertools.permutations(L, 3):
    if a < b and a + b == c:
        triples.append((a, b, c))
# Backtracking search
used = set()
solution = []

def search(start):
    if len(solution) == 15:
        # success
        witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}
        print(f"WITNESS: {json.dumps(witness)}")
        sys.exit(0)
    if start >= len(triples):
        return
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        used.update([a, b, c])
        solution.append((a, b, c))
        search(i + 1)
        solution.pop()
        used.difference_update([a, b, c])
    return
search(0)
# If no solution found
witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}
print(f"WITNESS: {json.dumps(witness)}")

import sys, json

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
Lset = set(L)

# Precompute possible triples (a,b,c) where a+b=c and all three in L
triples = []
for a in L:
    for b in L:
        if a >= b:  # avoid duplicates, order not important
            continue
        c = a + b
        if c in Lset:
            triples.append((a, b, c))

# Sort triples to try smaller numbers first (helps pruning)
triples.sort()

used = set()
solution = []

sys.setrecursionlimit(10000)

def backtrack():
    if len(solution) == 15:
        return True
    # pick the smallest unused number as a
    for a in L:
        if a not in used:
            break
    else:
        return False
    # try all triples containing this a
    for (x, y, z) in triples:
        if a not in (x, y):
            continue
        if x in used or y in used or z in used:
            continue
        # choose ordering so that a is one of the addends
        used.update([x, y, z])
        solution.append((x, y, z))
        if backtrack():
            return True
        # backtrack
        used.difference_update([x, y, z])
        solution.pop()
    return False

found = backtrack()
if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}
    print(f"WITNESS: {json.dumps(witness)}")
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}
    print(f"WITNESS: {json.dumps(witness)}")
